CREATE TABLE proposal_operation_keys(project_id uuid NOT NULL,run_id uuid NOT NULL,idempotency_key text NOT NULL,actor_id uuid NOT NULL REFERENCES members,input_hash text NOT NULL,proposal_id uuid NOT NULL,proposal_version integer NOT NULL,PRIMARY KEY(run_id,idempotency_key),FOREIGN KEY(proposal_id,proposal_version) REFERENCES request_proposals(id,version),FOREIGN KEY(run_id,project_id) REFERENCES scenario_runs(id,project_id));
